// Data access for bookmarks and tags (data-model.md; FR-003/007/008/009/010-014).
import { normalizeUrl } from './lib/url.js';
import { fetchTitle } from './lib/title.js';

export class DuplicateUrlError extends Error {
  constructor(message = 'This URL is already bookmarked.') {
    super(message);
    this.code = 'duplicate_url';
  }
}

export class NotFoundError extends Error {
  constructor(message = 'Bookmark not found.') {
    super(message);
    this.code = 'not_found';
  }
}

const MAX_TAG_LENGTH = 50;

export function createRepository(db, { titleFetcher = fetchTitle } = {}) {
  // --- tag helpers -----------------------------------------------------------
  const insertTag = db.prepare('INSERT OR IGNORE INTO tags(name) VALUES (?)');
  const findTag = db.prepare('SELECT id FROM tags WHERE name = ?');
  const linkTag = db.prepare(
    'INSERT OR IGNORE INTO bookmark_tags(bookmark_id, tag_id) VALUES (?, ?)'
  );
  const unlinkAll = db.prepare('DELETE FROM bookmark_tags WHERE bookmark_id = ?');
  const pruneOrphans = db.prepare(
    'DELETE FROM tags WHERE id NOT IN (SELECT DISTINCT tag_id FROM bookmark_tags)'
  );

  function normalizeTags(tags) {
    if (!Array.isArray(tags)) return [];
    const seen = new Set();
    for (const raw of tags) {
      if (typeof raw !== 'string') continue;
      const name = raw.trim().toLowerCase().slice(0, MAX_TAG_LENGTH);
      if (name) seen.add(name);
    }
    return [...seen];
  }

  function setTags(bookmarkId, tags) {
    unlinkAll.run(bookmarkId);
    for (const name of normalizeTags(tags)) {
      insertTag.run(name);
      const { id } = findTag.get(name);
      linkTag.run(bookmarkId, id);
    }
    pruneOrphans.run();
  }

  function tagsFor(bookmarkId) {
    return db
      .prepare(
        `SELECT t.name FROM tags t
         JOIN bookmark_tags bt ON bt.tag_id = t.id
         WHERE bt.bookmark_id = ? ORDER BY t.name`
      )
      .all(bookmarkId)
      .map((r) => r.name);
  }

  function toBookmark(row) {
    if (!row) return null;
    return {
      id: row.id,
      url: row.url,
      title: row.title,
      tags: tagsFor(row.id),
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }

  // --- queries ---------------------------------------------------------------
  const byId = db.prepare('SELECT * FROM bookmarks WHERE id = ?');
  const byUrl = db.prepare('SELECT * FROM bookmarks WHERE url = ?');

  async function resolveTitle(url, customTitle) {
    if (typeof customTitle === 'string' && customTitle.trim() !== '') {
      return customTitle.trim();
    }
    const fetched = await titleFetcher(url);
    return fetched && fetched.trim() !== '' ? fetched.trim() : url;
  }

  return {
    /** List bookmarks, newest first, with optional keyword + tag filters. */
    list({ q = '', tags = [] } = {}) {
      const conditions = [];
      const params = [];

      const keyword = typeof q === 'string' ? q.trim() : '';
      if (keyword) {
        const like = `%${keyword.toLowerCase()}%`;
        conditions.push(`(
          LOWER(b.url) LIKE ? OR LOWER(b.title) LIKE ? OR b.id IN (
            SELECT bt.bookmark_id FROM bookmark_tags bt
            JOIN tags t ON t.id = bt.tag_id WHERE LOWER(t.name) LIKE ?
          )
        )`);
        params.push(like, like, like);
      }

      const tagList = normalizeTags(tags);
      for (const name of tagList) {
        conditions.push(`b.id IN (
          SELECT bt.bookmark_id FROM bookmark_tags bt
          JOIN tags t ON t.id = bt.tag_id WHERE t.name = ?
        )`);
        params.push(name);
      }

      const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
      const rows = db
        .prepare(`SELECT b.* FROM bookmarks b ${where} ORDER BY b.created_at DESC, b.id DESC`)
        .all(...params);
      return rows.map(toBookmark);
    },

    getById(id) {
      return toBookmark(byId.get(id));
    },

    async create({ url, title, tags } = {}) {
      const normalized = normalizeUrl(url); // throws InvalidUrlError
      if (byUrl.get(normalized)) throw new DuplicateUrlError();

      const finalTitle = await resolveTitle(normalized, title);
      const now = new Date().toISOString();

      const tx = db.transaction(() => {
        const info = db
          .prepare(
            'INSERT INTO bookmarks(url, title, created_at, updated_at) VALUES (?,?,?,?)'
          )
          .run(normalized, finalTitle, now, now);
        setTags(info.lastInsertRowid, tags);
        return info.lastInsertRowid;
      });
      return this.getById(tx());
    },

    async update(id, { url, title, tags } = {}) {
      const existing = byId.get(id);
      if (!existing) throw new NotFoundError();

      let normalized = existing.url;
      if (url !== undefined) {
        normalized = normalizeUrl(url); // throws InvalidUrlError
        const clash = byUrl.get(normalized);
        if (clash && clash.id !== id) throw new DuplicateUrlError();
      }

      // Title: explicit non-empty wins; blank/omitted keeps existing unless url changed.
      let finalTitle = existing.title;
      if (typeof title === 'string' && title.trim() !== '') {
        finalTitle = title.trim();
      } else if (url !== undefined && normalized !== existing.url && (title === '' || title === undefined)) {
        finalTitle = await resolveTitle(normalized, undefined);
      }

      const now = new Date().toISOString();
      const tx = db.transaction(() => {
        db.prepare(
          'UPDATE bookmarks SET url = ?, title = ?, updated_at = ? WHERE id = ?'
        ).run(normalized, finalTitle, now, id);
        if (tags !== undefined) setTags(id, tags);
      });
      tx();
      return this.getById(id);
    },

    remove(id) {
      const info = db.prepare('DELETE FROM bookmarks WHERE id = ?').run(id);
      if (info.changes === 0) throw new NotFoundError();
      pruneOrphans.run();
      return true;
    },

    listTags() {
      return db
        .prepare(
          `SELECT t.name AS name, COUNT(bt.bookmark_id) AS count
           FROM tags t LEFT JOIN bookmark_tags bt ON bt.tag_id = t.id
           GROUP BY t.id ORDER BY t.name`
        )
        .all();
    },
  };
}
// SQLite connection and schema initialization (data-model.md, research.md).
import Database from 'better-sqlite3';
import { mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DEFAULT_DB_PATH = join(__dirname, '..', 'data', 'bookmarks.db');

/**
 * Open (or create) the database and ensure the schema exists.
 * @param {string} [dbPath] override path (":memory:" for tests)
 * @returns {import('better-sqlite3').Database}
 */
export function openDatabase(dbPath = process.env.BOOKMARKS_DB || DEFAULT_DB_PATH) {
  if (dbPath !== ':memory:') {
    mkdirSync(dirname(dbPath), { recursive: true });
  }
  const db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  initSchema(db);
  return db;
}

function initSchema(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS bookmarks (
      id         INTEGER PRIMARY KEY AUTOINCREMENT,
      url        TEXT NOT NULL UNIQUE,
      title      TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS tags (
      id   INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE
    );

    CREATE TABLE IF NOT EXISTS bookmark_tags (
      bookmark_id INTEGER NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
      tag_id      INTEGER NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
      PRIMARY KEY (bookmark_id, tag_id)
    );

    CREATE INDEX IF NOT EXISTS idx_bookmarks_created ON bookmarks(created_at DESC);
  `);
}
// /api/bookmarks routes (contracts/api.md).
import { Router } from 'express';

export function bookmarksRouter(repo) {
  const router = Router();

  // GET /api/bookmarks?q=&tag=&tag=
  router.get('/', (req, res) => {
    const q = typeof req.query.q === 'string' ? req.query.q : '';
    const tag = req.query.tag;
    const tags = Array.isArray(tag) ? tag : tag ? [tag] : [];
    res.json({ bookmarks: repo.list({ q, tags }) });
  });

  // POST /api/bookmarks
  router.post('/', async (req, res, next) => {
    try {
      const { url, title, tags } = req.body ?? {};
      const bookmark = await repo.create({ url, title, tags });
      res.status(201).json({ bookmark });
    } catch (err) {
      next(err);
    }
  });

  // GET /api/bookmarks/:id
  router.get('/:id', (req, res, next) => {
    const bookmark = repo.getById(Number(req.params.id));
    if (!bookmark) return next(Object.assign(new Error('Bookmark not found.'), { code: 'not_found' }));
    res.json({ bookmark });
  });

  // PUT /api/bookmarks/:id
  router.put('/:id', async (req, res, next) => {
    try {
      const { url, title, tags } = req.body ?? {};
      const bookmark = await repo.update(Number(req.params.id), { url, title, tags });
      res.json({ bookmark });
    } catch (err) {
      next(err);
    }
  });

  // DELETE /api/bookmarks/:id
  router.delete('/:id', (req, res, next) => {
    try {
      repo.remove(Number(req.params.id));
      res.status(204).end();
    } catch (err) {
      next(err);
    }
  });

  return router;
}
// /api/tags route (contracts/api.md).
import { Router } from 'express';

export function tagsRouter(repo) {
  const router = Router();

  // GET /api/tags -> { tags: [{ name, count }] }
  router.get('/', (_req, res) => {
    res.json({ tags: repo.listTags() });
  });

  return router;
}
// Best-effort page-title fetching (research.md Decision 4, FR-003).
// Never throws: on any failure it returns null so callers fall back to the URL.

const FETCH_TIMEOUT_MS = 5000;
const MAX_BYTES = 512 * 1024; // 512 KB cap — titles appear early in <head>.

/**
 * Extract the text of the first <title> element from an HTML string.
 * @param {string} html
 * @returns {string|null}
 */
export function extractTitle(html) {
  if (typeof html !== 'string') return null;
  const match = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (!match) return null;
  const text = decodeBasicEntities(match[1]).replace(/\s+/g, ' ').trim();
  return text === '' ? null : text;
}

function decodeBasicEntities(s) {
  return s
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'");
}

/**
 * Fetch a page and return its <title>, or null on any failure/timeout/non-HTML.
 * @param {string} url normalized http/https URL
 * @param {(url: string, opts: object) => Promise<Response>} [fetchImpl] injectable for tests
 * @returns {Promise<string|null>}
 */
export async function fetchTitle(url, fetchImpl = globalThis.fetch) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
  try {
    const res = await fetchImpl(url, {
      signal: controller.signal,
      redirect: 'follow',
      headers: { 'user-agent': 'BookmarkManager/1.0' },
    });
    if (!res.ok) return null;

    const contentType = res.headers?.get?.('content-type') || '';
    if (contentType && !contentType.includes('text/html')) return null;

    const html = await readCapped(res);
    return extractTitle(html);
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

async function readCapped(res) {
  // Prefer streaming so we can stop after MAX_BYTES; fall back to text().
  if (res.body && typeof res.body.getReader === 'function') {
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let out = '';
    let received = 0;
    while (received < MAX_BYTES) {
      const { done, value } = await reader.read();
      if (done) break;
      received += value.byteLength;
      out += decoder.decode(value, { stream: true });
      if (/<\/title>/i.test(out)) break; // got what we need
    }
    try {
      await reader.cancel();
    } catch {
      /* ignore */
    }
    return out;
  }
  return await res.text();
}
// URL validation and normalization for bookmarks.
// Accepts only http/https web addresses; normalizes for storage and duplicate
// detection (data-model.md, FR-002, FR-009).

export class InvalidUrlError extends Error {
  constructor(message = 'Please enter a valid http or https web address.') {
    super(message);
    this.code = 'invalid_url';
  }
}

const DEFAULT_PORTS = { 'http:': '80', 'https:': '443' };

/**
 * Validate and normalize a web address.
 * @param {string} input raw user-supplied address
 * @returns {string} normalized absolute URL
 * @throws {InvalidUrlError} if malformed or not http/https
 */
export function normalizeUrl(input) {
  if (typeof input !== 'string' || input.trim() === '') {
    throw new InvalidUrlError('A web address is required.');
  }

  let url;
  try {
    url = new URL(input.trim());
  } catch {
    throw new InvalidUrlError();
  }

  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    throw new InvalidUrlError('Only http and https web addresses are supported.');
  }

  // Lowercase scheme and host (URL already lowercases these), strip default port.
  if (url.port && DEFAULT_PORTS[url.protocol] === url.port) {
    url.port = '';
  }

  // Collapse an empty path to "/".
  if (url.pathname === '') {
    url.pathname = '/';
  }

  return url.toString();
}

/**
 * Validate without throwing.
 * @returns {boolean}
 */
export function isValidUrl(input) {
  try {
    normalizeUrl(input);
    return true;
  } catch {
    return false;
  }
}
